p=os.path.join(os.environ['APPDATA'],'Code','User','globalStorage','state.vscdb')
c=sqlite3.connect('file:'+p.replace('\\','/')+'?mode=ro',uri=True)
r=c.execute('SELECT value FROM ItemTable WHERE key=?',('extensionsAssignmentFilterProvider.copilotSku',)).fetchone()
if r:
 v=r[0]
 if isinstance(v,bytes): v=v.decode('utf-8','ignore')
 allowed={'free','pro','pro+','business','enterprise','individual','unknown',''}
 norm=str(v).strip().lower()
 print('COPILOT_SKU=' + (norm if norm in allowed else 'UNRECOGNIZED_OR_UNSAFE_TO_DISPLAY'))
else: print('COPILOT_SKU=NOT_AVAILABLE')
c.close()
root=os.path.join(os.environ['APPDATA'],'Code','User','workspaceStorage')
found=False
if os.path.isdir(root):
 for d in os.listdir(root):
  w=os.path.join(root,d,'workspace.json')
  try: data=json.load(open(w,encoding='utf-8'))
  except Exception: continue
  s=json.dumps(data).lower()
  if 'a:\\dsh-core' in s or 'a:/dsh-core' in s:
   found=True
   print('TARGET_WORKSPACE_RECORD_PRESENT=True')
   db=os.path.join(root,d,'state.vscdb')
   if os.path.isfile(db):
    q=sqlite3.connect('file:'+db.replace('\\','/')+'?mode=ro',uri=True)
    for (k,) in q.execute('SELECT key FROM ItemTable'):
     if 'trust' in k.lower() or 'restricted' in k.lower(): print('WORKSPACE_TRUST_STATE_KEY='+k)
    q.close()
if not found: print('TARGET_WORKSPACE_RECORD_PRESENT=False')
